      SUBROUTINE ELSTORC---- STORE ELEMENT IN DATA ARRAYSC--------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1B.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA1D.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2C.CIN'      INCLUDE 'DATUM.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'ILAST.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'LIMITS.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'RDPRNT.CIN'      INCLUDE 'RDWRDS.CIN'      INCLUDE 'VARY.CIN'C-----------------------------------------------------------------------      CHARACTER*1     ILIM      INTEGER         TEXTC      IF (NTYPE .EQ. 0) THEN        IF (.NOT. LIST) GO TO 400        ILIM = BLANK        IF (LABLE .NE. BLANK) ILIM = APOST        WRITE (NOUT,9700) ILIM, LABLE, ILIM, CMMNT, PARENC 9700   FORMAT (2H  ,A1,A8,A1,2H (,79A1)        GO TO 400      ENDIFC      IF (.NOT. LIST .OR. .NOT. RFM .OR. NWORD .EQ. 0) GO TO 110      CALL PRINT1(LABLE,NWORD,DATUM,VARY,0)CC     READ NEW DATA DECKC  110 NEL = NEL + 1      ILAST = IC      IF (NEL .GT. NELLIM .OR. (I + NWORD) .GT. IDLIM) THEN        FLUSHL = .TRUE.        IF (NEL .GT. NELLIM) WRITE (NOUT,9001) NEL, NELLIM 9001   FORMAT (' *** DATA OVERFLOW, NUMBER OF ELEMENTS IS ',I5,2X,     1          'LIMIT IS ',I5,' ***')        IF (I + NWORD .GT. IDLIM) WRITE (NOUT,9002) I + NWORD, IDLIM 9002   FORMAT (' *** DATA OVERFLOW, NUMBER OF DATA ITEMS IS ',I5,2X,     1          'LIMIT IS ',I5,' ***')      ENDIF      IF (FLUSHL) GO TO 150      NDESCR(NEL) = NDESC      LABEL(NEL) = LABLE      LBTYP(NEL) = KTYPE      IF (NWORD .EQ. 0) GO TO 140C            DO 125 J = 1, NWORD      DATA(I) = DATUM(J)      TIE (I) = VARY (J)  125 I = I + 1C            IF (NWORD .GT. 1) THEN        DO 135 J = 2, NWORD        DATUM(J) = 0.0        VARY(J) = 0  135   CONTINUE      ENDIFC  140 ISTOR(NEL+1) = I      GO TO 400C  150 I = I + NWORDC  400 CONTINUE      RETURN      END